SELECT ?p ?s (SAMPLE(?id) AS ?tid) WHERE {
  ?z a brick:Perimeter_zone .
  FILTER(str(?z) ENDS_WITH "Perimeter_mid_ZN_4")
  ?m brick:hasSubNetwork ?z ; ref:hasExternalReference ?p ; ref:hasTimeseriesId ?id ; a brick:AirTemperatureSensor .
}
GROUP BY ?p ?s

SELECT DISTINCT ?id ?class ?label WHERE {
  ?s ref:hasExternalReference ?x ; ref:hasTimeseriesId ?id .
  ?x a ?class .
  ?x brick:hasSubNetwork ?z .
  ?z rdfs:label ?label .
}

SELECT DISTINCT ?label WHERE {
  ?z a brick:Perimeter_zone .
  ?z rdfs:label ?label .
}

SELECT DISTINCT ?class WHERE {
  ?s ref:hasExternalReference ?x ; ref:hasTimeseriesId ?id .
  ?x a ?class .
}

SELECT DISTINCT ?class WHERE {
  ?z a brick:Perimeter_zone .
  ?z a ?class .
}

